    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for pos, event in enumerate(data["events"]):
            if event.get("sequence", 0) > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(pos))
            key = (event.get("revision", 0), pos)
            if event_id not in winners or key > winners[event_id][0]:
                winners[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, data["rounding"])
            tax = rounded(raw * event.get("tax_bp", 0), 10000, data["rounding"])
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}

    return solve


def _build_component_07():
    from itertools import combinations

    def solve(data):
        k = data["k"]
        blocked = set(data.get("blocked", []))
        jobs = [j for j in data["jobs"] if j["id"] not in blocked]
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best_ids = None
        best_value = None
        for subset in combinations(jobs, k):
            ids = {j["id"] for j in subset}
            if not mandatory <= ids:
                continue
            counts = {}
            for job in subset:
                group = job["group"]
                counts[group] = counts.get(group, 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            ordered = sorted(subset, key=lambda j: (j["start"], j["end"], j["id"]))
            valid = True
            for i, first in enumerate(ordered):
                overlap = 0
                for other in ordered:
                    if first["start"] < other["end"] and other["start"] < first["end"]:
                        overlap += 1
                if overlap > 2:
                    valid = False
                    break
            if not valid:
                continue
            value = sum(j["value"] for j in subset)
            selected = sorted(ids)
            if (best_ids is None or value > best_value or
                    (value == best_value and selected > best_ids)):
                best_ids, best_value = selected, value
        if best_ids is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}

    return solve


def _build_component_08():
    import heapq

    def solve(data):
        required = data.get("required", [])
        bits = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)
        source = data["source"]
        initial_mask = bits.get(source, 0)
        start_state = (source, initial_mask, data["coupons"])
        distances = {start_state: data["start"]}
        queue = [(data["start"], source, initial_mask, data["coupons"])]

        while queue:
            time, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if distances.get(state) != time:
                continue
            if node == data["target"] and mask == full:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                durations = [(edge["duration"], remaining)]
                if remaining:
                    durations.append((max(1, edge["duration"] - edge.get("discount", 0)),
                                      remaining - 1))
                for duration, next_remaining in durations:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    next_node = edge["v"]
                    next_mask = mask | bits.get(next_node, 0)
                    next_state = (next_node, next_mask, next_remaining)
                    if arrival < distances.get(next_state, float("inf")):
                        distances[next_state] = arrival
                        heapq.heappush(queue, (arrival, next_node, next_mask, next_remaining))
        return {"arrival": None}

    return solve


